<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create,rerun} from '../api/comparisons';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import DiffHistogram from '../components/DiffHistogram.vue';import {num,pct,short} from '../utils/format';
const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();
const name=ref('通道加固·新配对比较'),base=ref('demo-scenario'),compareTo=ref('demo-scenario-compressed'),samples=ref(1500),seed=ref(2410),id=ref('');
const{busy,error,notice,act}=useAction();
const item=computed(()=>props.data.comparisons.find(c=>c.id===id.value)||props.data.comparisons[0]);
const result=computed(()=>item.value?.status==='completed'?item.value.result:null);
const scenarioName=(sid:string)=>props.data.scenarios.find(s=>s.id===sid)?.name||short(sid);</script><template><Heading index="07 / PAIRED COMPARISON" title="同一随机分位，才看得出赶工差。" detail="两份冻结情景共用逐任务随机分位流：同一task_id在每个样本取相同分位，再按各自三点工期与FS依赖重算CPM。独立推演直接相减会把抽样噪声当成改善；配对后噪声抵消，剩下的才是方案差异。"/><section v-if="canWrite" class="form-section"><form class="form-grid" @submit.prevent="act(async()=>{await create({name,base_scenario_id:base,compare_scenario_id:compareTo,samples,seed});await refresh()},'配对比较已冻结两份快照并提交后台')"><label>比较名称<input aria-label="比较名称" v-model="name" required/></label><label>基准情景<select aria-label="基准情景" v-model="base"><option v-for="s in data.scenarios" :key="s.id" :value="s.id">{{s.name}} · v{{s.version}}</option></select></label><label>对比情景<select aria-label="对比情景" v-model="compareTo"><option v-for="s in data.scenarios" :key="s.id" :value="s.id">{{s.name}} · v{{s.version}}</option></select></label><label>模拟样本数<input aria-label="模拟样本数" type="number" min="100" max="5000" step="1" v-model.number="samples"/></label><label>固定seed<input aria-label="固定seed" type="number" min="0" max="2147483647" step="1" v-model.number="seed"/></label><button class="primary" :disabled="busy">冻结并提交配对比较</button></form><Notice :error="error" :notice="notice"/></section><Empty v-if="!data.scenarios.length">先在风险情景页冻结两份情景，再选择基准与对比做配对比较。</Empty><Empty v-else-if="!data.comparisons.length">尚无配对比较。选择基准与对比情景，冻结后由后台按公共随机分位计算工期差。</Empty><template v-else><label class="selector">回看已保存的配对比较<select aria-label="回看已保存的配对比较" v-model="id"><option v-for="c in data.comparisons" :key="c.id" :value="c.id">{{c.name}} · {{c.status}} · {{short(c.id)}}</option></select></label><template v-if="item"><div class="result-meta"><Status :value="item.status"/><span>比较 {{short(item.id)}}</span><span>基准 v{{item.base_version}} / 对比 v{{item.compare_version}}</span><span v-if="result">SHA256 {{short(result.checksum)}}</span></div><p v-if="item.status==='queued'||item.status==='running'" role="status" class="notice">后台正在按公共随机分位逐样本重算两侧CPM，完成后自动刷新。</p><p v-if="item.status==='failed'" role="alert" class="notice error">{{item.error}} · 调整输入后新建比较重试，失败记录保留。</p><div class="scenario-strip"><span>基准 <b>{{scenarioName(item.base_scenario_id)}} · v{{item.base_version}}</b></span><span>对比 <b>{{scenarioName(item.compare_scenario_id)}} · v{{item.compare_version}}</b></span><span>抽样 <b>{{item.samples}}</b></span><span>seed <b>{{item.seed}}</b></span><span>模型 <b>公共分位 Beta-PERT λ=4</b></span></div><template v-if="result"><div class="risk-summary"><div><small>提前样本比例（对比更早完工）</small><b>{{pct(result.diff.ahead_ratio)}}</b><span>{{result.diff.ahead_count}} / {{result.diff.denominator}} · 差&lt;−{{result.tolerance_hours}}h</span></div><div><small>持平样本比例</small><b>{{pct(result.diff.on_par_ratio)}}</b><span>{{result.diff.on_par_count}} / {{result.diff.denominator}} · |差|≤{{result.tolerance_hours}}h</span></div><div><small>延后样本比例（对比更晚完工）</small><b>{{pct(result.diff.delayed_ratio)}}</b><span>{{result.diff.delayed_count}} / {{result.diff.denominator}} · 差&gt;+{{result.tolerance_hours}}h</span></div></div><DiffHistogram :diff="result.diff"/><div class="quantiles"><span v-for="(v,k) in result.diff.quantiles" :key="k">{{k}} <b>{{num(v)}}h</b></span><span>均值差 <b>{{num(result.diff.mean)}}h</b></span><span>基准均值 <b>{{num(result.base.mean_finish)}}h</b></span><span>对比均值 <b>{{num(result.compare.mean_finish)}}h</b></span></div><p class="muted">工期差=对比情景完工−基准情景完工，逐样本配对计算；截止期不参与，截止期变化不影响工期差。分位采用(n−1)q位置线性插值；有限样本结果，不是承诺。</p><div class="section-rule"><h2>任务配对口径</h2><span>分位流按 paired|seed|task_id 派生，与任务顺序和集合无关</span></div><div class="quantiles"><span>共同任务 <b>{{result.common_tasks.length}}</b></span><span>仅基准 <b>{{result.only_base.length}}</b></span><span>仅对比 <b>{{result.only_compare.length}}</b></span></div><p v-if="result.only_base.length||result.only_compare.length" class="muted">仅基准：{{result.only_base.join('、')||'无'}}；仅对比：{{result.only_compare.join('、')||'无'}}。独有任务只影响所属情景，既有任务分位不变，增删或重排后仍可复现。</p><details><summary>模型假设、快照校验和与全部工期差样本</summary><p v-for="s in result.assumptions" :key="s">{{s}}</p><p class="mono">{{result.checksum}}</p><p class="mono">{{result.diff.values.map(v=>num(v,4)).join(' / ')}}</p></details></template><div v-if="canWrite" class="actions"><button :disabled="busy" @click="act(async()=>{await rerun(item!.id);await refresh()},'已按原快照重新提交重算，结果与首次逐位一致')">按原快照重算 ↻</button><small class="muted">重算只读取本记录冻结的两份快照；上游工作包更新不影响结果。</small></div></template></template><p class="footnote">配对比较保存来源情景版本与完整快照，可在本页随时回看；原独立推演运行、交付复核与已批准报告保持不变。</p></template>
